// Orders and Subscriptions go through PayPal's Server SDK (generated by APIMatic), over Upstream's own transport.
// These tests look at what actually reaches PayPal: the request the SDK builds, the shared token, the call log, and errors.
import "./helpers/env.ts";
import { test, before } from "node:test";
import assert from "node:assert/strict";
import { db, openDb, setDbForTests } from "../src/db.ts";
import { PayPalError, setPayPalFetch } from "../src/paypal/client.ts";
import { captureOrder, createOrder, getOrder } from "../src/paypal/orders.ts";
import { getSubscription, listSubscriptionTransactions } from "../src/paypal/subscriptions.ts";
import { SDK_PACKAGE, SDK_VERSION } from "../src/paypal/sdk.ts";

type Seen = { method: string; path: string; search: string; headers: Headers; body: string };
const seen: Seen[] = [];
let tokenCalls = 0;

const json = (status: number, body: unknown, extra: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "paypal-debug-id": `dbg-${seen.length}`, ...extra } });

before(() => {
  setDbForTests(openDb(":memory:"));
  setPayPalFetch((async (input: string | URL | Request, init?: RequestInit) => {
    const url = new URL(String(input));
    if (url.pathname === "/v1/oauth2/token") {
      tokenCalls++;
      return json(200, { access_token: "app-token", token_type: "Bearer", expires_in: 3600 });
    }
    seen.push({ method: String(init?.method), path: url.pathname, search: url.search, headers: new Headers(init?.headers), body: String(init?.body ?? "") });
    if (url.pathname === "/v2/checkout/orders") {
      return json(201, { id: "O-1", status: "PAYER_ACTION_REQUIRED", links: [{ rel: "payer-action", href: "https://www.sandbox.paypal.com/checkoutnow?token=O-1", method: "GET" }] });
    }
    if (url.pathname === "/v2/checkout/orders/O-1/capture") {
      return json(422, { name: "UNPROCESSABLE_ENTITY", message: "The requested action could not be performed.", details: [{ issue: "ORDER_NOT_APPROVED" }] });
    }
    if (url.pathname === "/v2/checkout/orders/O-1") return json(200, { id: "O-1", status: "PAYER_ACTION_REQUIRED" });
    if (url.pathname === "/v1/billing/subscriptions/I-1") return json(200, { id: "I-1", plan_id: "P-1", status: "ACTIVE" });
    if (url.pathname === "/v1/billing/subscriptions/I-1/transactions") {
      return json(200, { transactions: [{ id: "T-1", status: "COMPLETED", time: "2026-11-06T00:24:00Z", amount_with_breakdown: { gross_amount: { currency_code: "USD", value: "10.00" }, fee_amount: { currency_code: "USD", value: "0.84" } } }] });
    }
    return json(404, { name: "RESOURCE_NOT_FOUND" });
  }) as typeof fetch);
});

test("the SDK is APIMatic's PayPal Server SDK, and its version is known", () => {
  assert.equal(SDK_PACKAGE, "@paypal/paypal-server-sdk");
  assert.match(SDK_VERSION, /^\d+\.\d+\.\d+/);
});

test("createOrder: the SDK sends PayPal's own JSON, the idempotency key and Prefer, with Upstream's token", async () => {
  const { order, approveUrl } = await createOrder({ id: "top_abc", value: "5.00", currency: "USD", description: "Upstream pool top-up", returnUrl: "https://x.test/r", cancelUrl: "https://x.test/c" });
  assert.equal(order.id, "O-1");
  assert.equal(approveUrl, "https://www.sandbox.paypal.com/checkoutnow?token=O-1");
  const req = seen.find((s) => s.path === "/v2/checkout/orders")!;
  assert.equal(req.method, "POST");
  assert.equal(req.headers.get("paypal-request-id"), "top_abc");
  assert.equal(req.headers.get("prefer"), "return=representation");
  assert.equal(req.headers.get("authorization"), "Bearer app-token");
  // The SDK's typed, camelCase models go out as PayPal's snake_case JSON.
  const body = JSON.parse(req.body);
  assert.equal(body.intent, "CAPTURE");
  assert.deepEqual(body.purchase_units[0], { reference_id: "top_abc", amount: { currency_code: "USD", value: "5.00" }, description: "Upstream pool top-up", custom_id: "top_abc" });
  assert.deepEqual(body.payment_source.paypal.experience_context, { brand_name: "Upstream", shipping_preference: "NO_SHIPPING", return_url: "https://x.test/r", cancel_url: "https://x.test/c", user_action: "PAY_NOW" });
});

test("a PayPal error from the SDK becomes the same PayPalError a direct call throws", async () => {
  await assert.rejects(captureOrder("O-1", "top_abc-capture"), (e: unknown) => {
    assert.ok(e instanceof PayPalError);
    assert.equal(e.status, 422);
    assert.equal(e.errorName, "UNPROCESSABLE_ENTITY");
    assert.match(String(e.debugId), /^dbg-/);
    return true;
  });
  const cap = seen.find((s) => s.path === "/v2/checkout/orders/O-1/capture")!;
  assert.equal(cap.headers.get("paypal-request-id"), "top_abc-capture");
  assert.equal(cap.body, "{}");
  assert.equal((await getOrder("O-1")).data.status, "PAYER_ACTION_REQUIRED");
});

test("subscriptions: reads and the transaction list go through the SDK, with the time range as PayPal names it", async () => {
  assert.equal((await getSubscription("I-1")).data.status, "ACTIVE");
  const start = new Date("2026-11-01T00:00:00Z");
  const end = new Date("2026-11-07T00:00:00Z");
  const tx = await listSubscriptionTransactions("I-1", start, end);
  assert.equal(tx.data.transactions?.[0].amount_with_breakdown.fee_amount?.value, "0.84");
  const req = seen.find((s) => s.path === "/v1/billing/subscriptions/I-1/transactions")!;
  const q = new URLSearchParams(req.search);
  assert.equal(q.get("start_time"), start.toISOString());
  assert.equal(q.get("end_time"), end.toISOString());
});

test("every SDK call is in the PayPal call log marked sdk, and the SDK and direct calls share one token", () => {
  const rows = db().prepare("SELECT method, path, status, client, request_id, debug_id FROM paypal_calls ORDER BY id").all() as any[];
  assert.ok(rows.length >= 5);
  assert.ok(rows.every((r) => r.client === "sdk"), "all of these went through the SDK");
  const cap = rows.find((r) => r.path === "/v2/checkout/orders/O-1/capture");
  assert.equal(cap.status, 422);
  assert.equal(cap.request_id, "top_abc-capture");
  assert.match(cap.debug_id, /^dbg-/);
  assert.equal(tokenCalls, 1, "one token, fetched once by Upstream and handed to the SDK");
});
